'use client';

import { useId, useState } from 'react';
import './inline-validation.css';

export type ValidationResult =
  | { status: 'idle' }
  | { status: 'error'; message: string }
  | { status: 'success'; message: string };

export interface InlineValidationProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  validate: (value: string) => ValidationResult;
  /** Shown below the field before anything is checked. */
  hint?: string;
  className?: string;
}

/**
 * A field whose message slides between hint, error and success. Checking
 * starts after the first blur, then follows every keystroke. The message
 * area keeps a fixed height and is linked to the input.
 */
export function InlineValidation({
  label,
  value,
  onChange,
  validate,
  hint = '',
  className = '',
}: InlineValidationProps) {
  const [touched, setTouched] = useState(false);
  const id = useId();
  const result: ValidationResult = touched
    ? validate(value)
    : { status: 'idle' };
  const message = result.status === 'idle' ? hint : result.message;

  return (
    <div className={`mg-valid ${className}`} data-status={result.status}>
      <label htmlFor={id} className='mg-valid__label'>
        {label}
      </label>
      <div className='mg-valid__field'>
        <input
          id={id}
          className='mg-valid__input'
          value={value}
          aria-invalid={result.status === 'error'}
          aria-describedby={`${id}-message`}
          onChange={(event) => onChange(event.target.value)}
          onBlur={() => setTouched(true)}
        />
        <span className='mg-valid__icon' aria-hidden='true' />
      </div>
      <p id={`${id}-message`} className='mg-valid__message' aria-live='polite'>
        <span key={`${result.status}-${message}`}>
          {result.status === 'error'
            ? 'Error: '
            : result.status === 'success'
              ? 'OK: '
              : ''}
          {message}
        </span>
      </p>
    </div>
  );
}

.mg-valid {
  display: grid;
  gap: 6px;
  color: var(--mg-text, #ffffff);
}

.mg-valid__label {
  font-weight: 600;
}

.mg-valid__field {
  position: relative;
}

.mg-valid__input {
  width: 100%;
  height: 44px;
  padding: 0 40px 0 12px;
  border: 1.5px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  color: inherit;
  font: inherit;
  transition: border-color 200ms ease;
}

.mg-valid__input:focus-visible {
  outline: 3px solid #303030;
  border-color: var(--mg-accent-text, #648aff);
}

.mg-valid[data-status='error'] .mg-valid__input {
  border-color: #ffffff;
}

.mg-valid[data-status='success'] .mg-valid__input {
  border-color: #648aff;
}

/* One element draws the cross or the tick. */
.mg-valid__icon {
  position: absolute;
  top: 50%;
  right: 12px;
  width: 18px;
  height: 18px;
  margin-top: -9px;
  border-radius: 50%;
  transform: scale(0);
  transition: transform 260ms cubic-bezier(0.3, 1.6, 0.5, 1);
}

.mg-valid[data-status='error'] .mg-valid__icon,
.mg-valid[data-status='success'] .mg-valid__icon {
  transform: scale(1);
}

.mg-valid[data-status='error'] .mg-valid__icon {
  background: #262626;
}

.mg-valid[data-status='success'] .mg-valid__icon {
  background: #0047ff;
}

.mg-valid__icon::after {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  line-height: 18px;
  text-align: center;
}

.mg-valid[data-status='error'] .mg-valid__icon::after {
  content: '!';
}

.mg-valid[data-status='success'] .mg-valid__icon::after {
  content: '✓';
}

/* Fixed height, so a message appearing never pushes the layout around. */
.mg-valid__message {
  min-height: 2.6em;
  margin: 0;
  overflow: hidden;
  color: #b8b8b8;
  font-size: 13px;
}

.mg-valid__message > span {
  display: block;
  animation: mg-valid-in 220ms ease-out;
}

.mg-valid[data-status='error'] .mg-valid__message {
  color: #ffffff;
}

.mg-valid[data-status='success'] .mg-valid__message {
  color: #8aa8ff;
}

@keyframes mg-valid-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-valid__input,
  .mg-valid__icon {
    transition: none;
  }
  .mg-valid__message > span {
    animation: none;
  }
}
